insert into public.questoes (id, exame_id, recorte_id, banca, orgao, cargo, nivel, ano, numero, formato, disciplina, assunto, topico, lingua, texto_base_id, texto_apoio, comando, gabarito, dica1, dica2, explicacao, dificuldade) values
('2024-D2-Q095', 'enem', 'enem-BIO', 'INEP', null, null, 'Médio', 2024, 95, '5_alternativas', 'Biologia', 'Biotecnologia', 'RT-PCR e expressão gênica', null, null, 'O desenvolvimento da biotecnologia e da clonagem gênica em procariotos fez com que a produção de proteínas se tornasse mais intensa, rápida e econômica. Para a produção de hormônios, enzimas e proteínas de resistência a drogas, uma variação da técnica de reação em cadeia pela polimerase (PCR, na sigla em inglês) utiliza a enzima transcriptase reversa (RT-PCR), que sintetiza moléculas de DNA complementares a partir de fitas de RNA.', 'Nesse contexto, essa técnica é importante para detectar genes', 'A', 'A transcriptase reversa parte de RNA. Pense em quais genes geram RNA dentro da célula.', 'Um gene só vira RNA mensageiro quando está sendo transcrito, ou seja, quando está "ligado". A técnica copia esse RNA em DNA.', 'Resposta: A. A RT-PCR usa a transcriptase reversa para fazer DNA complementar a partir do RNA mensageiro presente na célula. Como só há mRNA de genes que estão sendo transcritos, a técnica detecta genes expressos. Ser plasmidial, bacteriano, dominante ou autossômico não tem relação com a presença de RNA, que é o que a técnica usa.', 'média'),
('2024-D2-Q098', 'enem', 'enem-BIO', 'INEP', null, null, 'Médio', 2024, 98, '5_alternativas', 'Biologia', 'Zoologia', 'Reprodução e anexos embrionários', null, null, 'Apesar de os animais representados no cladograma compartilharem um mesmo ancestral, eles se caracterizam por distintos padrões de reprodução ou de nutrição dos embriões e descendentes.
